const datestring = (value?: string) => value ? new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—';
const linesOf = (value: any) => Array.isArray(value) ? value.map(x=>x.content).join('\n') : '';
const profileLabel = (id: string | undefined, versions: Array<{ id: string; created_at: string }>, currentId?: string) => {
  const index = versions.findIndex(item => item.id === id);
  if (index < 0) return undefined;
  return `v${versions.length - index} · ${new Date(versions[index].created_at).toLocaleString('zh-CN')}${id === currentId ? ' · 当前版本' : ' · 历史版本'}`;
};

