          const failed = { ...latest, status: 'failed', error: { code: 'RESULT_PROCESSING_FAILED', message }, events: [...(latest.events ?? []), { sequence: (latest.events?.length ?? 0) + 1, type: 'results.failed', message, at: new Date().toISOString() }] };
