  async function waitOperation(id:string, onProgress?:(value:any)=>void) {
    for (let attempt=0;attempt<300;attempt++) {
      const value=await rpa(`/operations/${id}`);
      onProgress?.(value);
      if (value.status==='succeeded') return value;
      if (value.status==='failed'||value.status==='cancelled') throw new Error(value.error?.message??'操作未完成');
      await new Promise(resolve=>setTimeout(resolve,500));
    }
    throw new Error('操作超时，请检查平台浏览器后重试');
  }
  async function readSelectedJobJd(signed=false) {
    await execute(async()=>{
      const linked=jobs.find(item=>item.id===selectedJobId);
      if(!linked)throw new Error('请先选择已同步职位');
      const cached=linked.job_description??linked.jobDescription;
      if(cached){setJd(cached);setNotice('已读取已同步的职位描述');return;}
      if(!signed){setAgreementPurpose('jd');setAgreementRead(false);setAgreement(true);return;}
      if(!agreementRead)throw new Error('请先签署平台操作授权');
      if(!/^1[3-9]\d{9}$/.test(phone))throw new Error('请填写平台绑定手机号');
      setSyncProgress('正在打开 BOSS 职位管理并读取 JD');
      await rpa('/authorizations','POST',{platform:'boss',phone,authorized:true,signedAgreement:true});
      const opened=await rpa('/browser/open','POST',{platform:'boss',page:'jobs'});
      const ref=opened.browser?.sessionRef??opened.sessionRef;
      setSessionRef(ref);
      await showBrowser(true);
      const op=await rpa('/workflows/boss/job-description','POST',{sessionRef:ref,jobRef:linked.platform_job_ref??linked.platformJobRef,title:linked.title});
      const result=await waitOperation(op.operationId,state=>setSyncProgress(state.events?.at(-1)?.message??'正在读取 JD'));
      const text=String(result.result?.jobDescription??'').trim();
      if(!text)throw new Error('未读取到 JD，请改用粘贴 JD');
      setJd(text);
      setSyncProgress('JD 已读取');
      setNotice('已从 BOSS 职位读取 JD');
    });
  }
  async function nextWizard(){await execute(async()=>{
    if(wizardStep===0){setWizardStep(1);return;}
    if(wizardStep===1){if(!jdSource)throw new Error('请选择 JD 来源');if(jdSource==='paste'&&!jd.trim())throw new Error('请粘贴职位描述');setWizardStep(2);await refreshJobs();return;}
    if(wizardStep===2){if(platform!=='boss')throw new Error('当前仅 BOSS 直聘可运行自动化任务');if(jdSource==='sync'&&!selectedJobId)throw new Error('请选择已同步职位');if(!jobTitle.trim())throw new Error('请输入职位名称');if(!jd.trim())throw new Error('请先读取职位 JD，或返回选择粘贴 JD');setWizardStep(3);return;}
    if(!portrait){setLoading(true);try{const value=await cloud('/llm/profile','POST',{jd});setPortrait(value.profile);setProfileDraft({hardConditions:linesOf(value.profile?.hardConditions),businessConditions:linesOf(value.profile?.businessConditions),bonusItems:linesOf(value.profile?.bonusItems)});}finally{setLoading(false);}return;}
    const config={platform,recruitmentMode:mode,jdSource,platformJobId:selectedJobId,portrait,taskSettings:{maxQuickPerKeyword:maxQuick,maxRecommend,targetCount,targetStars},searchConfig:{enabled:true,platformJobId:selectedJobId,scenes:{search:true,recommend:false,push:false,review:false},keywords:[jobTitle],city:'',company:''}};
    const created=await cloud('/project','POST',{title:jobTitle,description:jd,recruitmentConfig:config});
    if(portrait){const version=await cloud(`/project/${created.id}/talent-profiles`,'POST',{profile:portrait});const updated=await cloud(`/project/${created.id}`,'PUT',{recruitmentConfig:{...config,profileVersionId:version.id}});await refreshProjects();openProject(updated);}else{await refreshProjects();openProject(created);}
    if(!localStorage.getItem('easyhunt-onboarded')){setTimeout(()=>driver({showProgress:true,steps:[{element:'#project-tabs',popover:{title:'职位工作区',description:'在这里查看简历、平台、画像和任务配置。'}},{element:'#task-control',popover:{title:'启动寻访',description:'签署授权后，任务在独立浏览器中运行。'}}]}).drive(),500);localStorage.setItem('easyhunt-onboarded','1');}
  });}
  async function saveProfile(){await execute(async()=>{if(!project)return;if(projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');const original=portrait??projectConfig(project).portrait??{};const profile:Object=Object.fromEntries((Object.keys(sectionNames) as AnalysisKey[]).map(key=>[key,profileDraft[key].split('\n').map(x=>x.trim()).filter(Boolean).map(content=>({content,evidence:(original[key]??[]).find((x:any)=>x.content===content)?.evidence??[]}))]));const version=await cloud(`/project/${project.id}/talent-profiles`,'POST',{profile});await saveProjectConfig({portrait:profile,profileVersionId:version.id});setPortrait(profile);setSelectedProfileVersion(version.id);await refreshProfileVersions(project.id);setNotice('人才画像已保存为新版本；旧简历分析保持原版本');});}
