  async function useProfileVersion(){await execute(async()=>{if(!project||!selectedProfileVersion)return;const version=profileVersions.find(item=>item.id===selectedProfileVersion);if(!version)throw new Error('画像版本不存在');await saveProjectConfig({portrait:version.profile,profileVersionId:version.id});setNotice('已切换当前画像版本；旧简历分析未重新评分');});}
  async function saveSearchConfig(){await execute(async()=>{if(!project)return;if(projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');const preview=previewBossConfig(searchConfig,project.title,jobs,Number(taskSettings.maxQuickPerKeyword??20));if(!preview.valid)throw new Error(preview.blockers.join('；'));await cloud(`/project/${project.id}/search-configs`,'PUT',{name:'当前平台配置',config:searchConfig});await saveProjectConfig({searchConfig});setNotice('平台配置已保存');});}
  async function saveTaskSettings(){await execute(async()=>{if(!project)return;if(projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');const next={...taskSettings,maxQuickPerKeyword:Number(taskSettings.maxQuickPerKeyword),maxRecommend:Number(taskSettings.maxRecommend)};if(!Number.isInteger(next.maxQuickPerKeyword)||!Number.isInteger(next.maxRecommend)||next.maxQuickPerKeyword<1||next.maxQuickPerKeyword>100||next.maxRecommend<1||next.maxRecommend>100)throw new Error('数量范围应为 1–100');if(!project.title.trim())throw new Error('请填写职位名称');await cloud(`/project/${project.id}/settings-versions`,'PUT',{settings:next});const updated=await cloud(`/project/${project.id}`,'PUT',{title:project.title.trim(),recruitmentConfig:{...projectConfig(project),taskSettings:next}});setProject(updated);setProjects(items=>items.map(item=>item.id===updated.id?updated:item));setTaskSettings(next);setNotice('任务配置已保存');});}
  async function archiveProject(value:Project){await execute(async()=>{const config={...projectConfig(value),archived:!projectConfig(value).archived};const updated=await cloud(`/project/${value.id}`,'PUT',{recruitmentConfig:config});setProjects(items=>items.map(item=>item.id===updated.id?updated:item));if(project?.id===updated.id)setProject(updated);setNotice(config.archived?'职位已归档':'职位已恢复');});}
  async function authorizeAndRun(signed=false){await execute(async()=>{if(!project)return;if(running)throw new Error('另一寻访任务正在运行，请等待完成或取消');if(platform!=='boss')throw new Error('当前仅 BOSS 直聘具备自动化 Skill');const config=projectConfig(project),search=config.searchConfig??{};const preview=previewBossConfig(search,project.title,jobs,Number(config.taskSettings?.maxQuickPerKeyword??20));if(config.recruitmentMode!=='target'&&!preview.valid)throw new Error(preview.blockers.join('；'));if(!signed){setAgreementPurpose('task');setAgreementRead(false);setAgreement(true);return;}if(!agreementRead)throw new Error('请先阅读并签署委托协议');if(!/^1[3-9]\d{9}$/.test(phone))throw new Error('请填写平台绑定手机号');if(!isLocalMode){const credits=await cloud('/billing/credits');if((credits.balance??0)<20)throw new Error('积分不足，任务已停止');}await rpa('/authorizations','POST',{platform,phone,authorized:true,signedAgreement:true});const opened=await rpa('/browser/open','POST',{platform,page:'search'});const ref=opened.browser?.sessionRef??opened.sessionRef;setSessionRef(ref);const payload=config.recruitmentMode==='target'?{recruitmentMode:'target',sessionRef:ref,projectId:project.id,jobTitle:project.title,profile:config.portrait}:{sessionRef:ref,...preview.parameters};const created=await rpa(config.recruitmentMode==='target'?'/workflows/boss/agent':'/workflows/boss/collect','POST',payload);processingOperation.current=false;localStorage.setItem('easyhunt-active-run',JSON.stringify({operationId:created.operationId,projectId:project.id,profile:config.portrait,profileVersionId:config.profileVersionId,platform,sessionRef:ref}));setRunContext({projectId:project.id,profile:config.portrait,profileVersionId:config.profileVersionId,platform});setOperation(created);setRunning(true);setPaused(false);await persistTaskRun(project.id,{...created,status:'pending',events:[]},platform);await showBrowser(true);});}
  /* DESIGN-DECISION: 无原始证据，自研 */
  /* DESIGN-DECISION: 无原始证据，自研 */
  async function syncJobs(signed=false){await execute(async()=>{
    if(!syncEnabled)throw new Error('请先在平台管理中启用 BOSS 职位同步');
    if(running)throw new Error('寻访任务正在运行，请先暂停或完成任务再同步职位');
    if(!signed){setAgreementPurpose('sync');setAgreementRead(false);setAgreement(true);return;}
    if(!agreementRead)throw new Error('请先签署委托协议');
    if(!/^1[3-9]\d{9}$/.test(phone))throw new Error('请填写平台绑定手机号');
    try {
    setSyncProgress('正在打开 BOSS 职位管理');
    await rpa('/authorizations','POST',{platform:'boss',phone,authorized:true,signedAgreement:true});
    const opened=await rpa('/browser/open','POST',{platform:'boss',page:'jobs'});
    const ref=opened.browser?.sessionRef??opened.sessionRef;
    setSessionRef(ref);
    await showBrowser(true);
    const op=await rpa('/operations','POST',{action:'jobs.list',sessionRef:ref,contextRef:'current-page'});
    const state=await waitOperation(op.operationId,value=>setSyncProgress(value.events?.at(-1)?.message??'正在读取职位'));
    const rows=state.result?.jobs??state.result?.items??[];
    if(!rows.length)throw new Error('BOSS 职位管理页未读取到职位，请确认招聘账号已登录且有已发布职位');
    const unique=[...new Map(rows.map((item:any)=>[item.jobRef,item])).values()] as any[];
    await cloud('/user/platform-jobs/sync','POST',{platform:'boss',jobs:unique.map(item=>({platform:'boss',platformJobRef:item.jobRef,title:item.title,city:item.city??undefined,status:item.status??'状态未知',jobDescription:item.jobDescription??undefined}))});
    await refreshJobs();
    setSyncProgress(`已同步 ${unique.length} 个职位`);
    setNotice(`已同步 ${unique.length} 个 BOSS 职位；重复职位已合并`);
    } catch (error) { setSyncProgress(`同步失败：${error instanceof Error ? error.message : String(error)}`); throw error; }
  });}
  async function control(action:'session.pause'|'session.resume'){await execute(async()=>{await rpa(`/sessions/${sessionRef}/control`,'POST',{action});setPaused(action==='session.pause');});}
  async function cancelOperation(){await execute(async()=>{if(!operation?.operationId)return;const value=await rpa(`/operations/${operation.operationId}/cancel`,'POST');setOperation(value);if(runContext)await persistTaskRun(runContext.projectId,value,runContext.platform);localStorage.removeItem('easyhunt-active-run');setRunning(false);setPaused(false);});}
  async function decide(ids:string[],status:string,reason=''){await execute(async()=>{if(!ids.length)throw new Error('请选择简历');if(project&&projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');await cloud('/resumes/decision','POST',{resumeIds:ids,decisionStatus:status,...(reason.trim()?{decisionReason:reason.trim()}:{})});setSelected([]);if(project)await refreshResumes(project.id);if(detailRow&&ids.includes(detailRow.id)){setDetailRow({...detailRow,status});setDecisionHistory((await cloud(`/resume/${detailRow.id}/decision-history`)).items??[]);}setNotice(`已更新 ${ids.length} 份简历`);});}
  async function openResume(row:Resume, keepReaderOrder=false){const value=await readLocalResume(row.local_ref);if(!value){setNotice('本地简历文件不存在，请检查存储目录');return;}if(!keepReaderOrder)setReaderIds(filteredResumes.map(item=>item.id));setDetail(value);setDetailRow(row);setDecisionHistory((await cloud(`/resume/${row.id}/decision-history`)).items??[]);}
  async function moveResume(direction:-1|1){if(!detailRow)return;const index=readerIds.indexOf(detailRow.id);const next=resumes.find(item=>item.id===readerIds[index+direction]);if(next)await openResume(next,true);}
  async function importResumes(){await execute(async()=>{
    if(!project)throw new Error('请先选择职位');
    if(projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');
    /* DESIGN-DECISION: 无原始证据，自研 */
    // An imported PDF is scored locally against explicit profile terms. When
    // those terms are absent, use the job title and leave unmatched evidence pending.
    const terms=(projectConfig(project).portrait?.hardConditions??[]).map((item:any)=>String(item.content??'').trim()).filter((item:string)=>item.length>0&&item.length<=60);
    const job={title:project.title,requiredSkills:terms.length?terms:[project.title],minimumDegree:'不限',minimumExperienceYears:0};
    setLoading(true);setNotice('正在本机解析所选 PDF 简历…');
    try{
      const result=await importLocalPdfs(job);
      if(!result){setNotice('已取消导入');return;}
      for(const item of result.candidates??[]){
        const record:LocalResume={name:item.resume.name,sourceText:item.sourceText,profileVersionId:projectConfig(project).profileVersionId,stars:item.score.stars,analysis:item.score.analysis,structured:item.resume,attachmentPath:item.localFiles.attachment,candidateRef:`pdf-${item.hash}`,createdAt:new Date().toISOString()};
        const saved=await saveLocalResume(record);
        await cloud('/resumes','POST',{projectId:project.id,localRef:saved.localRef,contentHash:item.hash,displayName:record.name,stars:record.stars,expectedCity:item.resume.expectedCity,expectedTitle:item.resume.expectedTitle});
      }
      await refreshResumes(project.id);
      setNotice(`本地导入 ${result.candidates?.length??0} 份；重复 ${result.filtered?.filter((item:any)=>item.reason==='duplicate').length??0} 份；失败 ${result.failed?.length??0} 份`);
    } finally {setLoading(false);}
  });}
  async function share(){await execute(async()=>{if(selected.length!==1)throw new Error('请选择一份简历分享');if(!shareConfirmed)throw new Error('请确认上传范围和有效期');if(!shareText.trim())throw new Error('请选择要上传的文字内容');const row=resumes.find(item=>item.id===selected[0])!;let recipients:any[]=[];if(shareAudience==='recipients'){const found=await cloud(`/resume/share-users/lookup?phone=${encodeURIComponent(sharePhone)}`);recipients=[{userId:found.user?.id??found.id,permission:sharePermission}];if(!recipients[0].userId)throw new Error('未找到协作账户');}const result=await cloud(`/resume/${row.id}/shares`,'POST',{audience:shareAudience,recipients,content:{sourceText:shareText.trim(),document:null},confirmed:true});setShareOpen(false);setShareConfirmed(false);setNotice(`分享已创建，有效期至 ${new Date(result.expiresAt).toLocaleDateString('zh-CN')}`);});}
  async function sendChat(){await execute(async()=>{if(!project||!chatText.trim())return;if(projectConfig(project).archived)throw new Error('归档职位为只读，请先恢复职位');let id=conversation;if(!id){const result=await cloud('/chat/conversations','POST',{projectId:project.id,title:project.title});id=result.id;setConversation(id);}await cloud(`/chat/conversations/${id}/messages`,'POST',{role:'user',content:chatText,workflowEvents:[]});setChat((await cloud(`/chat/conversations/${id}/messages`)).items??[]);setChatText('');});}
  const filteredProjects=useMemo(()=>projects.filter(item=>Boolean(projectConfig(item).archived)===archiveView&&(platformFilter==='all'||projectConfig(item).platform===platformFilter)&&item.title.toLowerCase().includes(search.toLowerCase())),[projects,archiveView,platformFilter,search]);
  const filteredResumes=useMemo(()=>resumes.filter(item=>(decisionFilter==='NEW'?isPendingDecision(item.status):item.status===decisionFilter)&&(platformFilter==='all'||item.platform===platformFilter)&&(!starFilter||item.stars>=starFilter)&&(`${item.display_name} ${localRecords[item.id]?.sourceText??''}`).toLowerCase().includes(search.toLowerCase())),[resumes,decisionFilter,platformFilter,starFilter,search,localRecords]);
  const projectOperation = runContext?.projectId === project?.id ? operation : null;
