  if(!token)return <div className="login"><div className="login-card"><span className="eyebrow">EASYHUNT / CLOUD</span><h1>登录云端账户</h1><p>本地模式无需登录。仅配置云服务时使用短信验证码。</p><input placeholder="手机号" value={phone} onChange={e=>setPhone(e.target.value)}/><button onClick={()=>execute(()=>cloud('/auth/send-code','POST',{phone}))}>发送验证码</button><input placeholder="验证码" value={code} onChange={e=>setCode(e.target.value)}/><button className="button-primary" onClick={()=>execute(async()=>{await cloud('/auth/login','POST',{phone,code});setToken(true);await refreshProjects();})}>登录</button>{notice&&<p className="error">{notice}</p>}</div></div>;
